{
  "justification": "Because the economy, unemployment and inflation dominate unprompted salience, proportionality (fair rewards, costs, and performance) is weighted highest, while healthcare, poverty, housing and environmental harms elevate care/harm. Crime/order and behaviour concerns point to authority, immigration/defence/EU to loyalty, and inequality/low pay/welfare and universal services to equality, with morality/drugs/environment anchoring a smaller sanctity/purity signal; as the instrument is directionless, weights reflect breadth and salience rather than policy lean.",
  "foundations": [
    {"foundation": "proportionality", "basis": "Economy/Economic situation; Unemployment/Factory closure/Lack of industry; Inflation/Prices; Taxation; Privatisation; Pound/Exchange rate/Value of Pound", "weight": 0.32},
    {"foundation": "care", "basis": "NHS/Hospitals/Healthcare; Poverty/Inequality; Housing; Pollution/Environment; Drug abuse; Education/Schools", "weight": 0.23},
    {"foundation": "authority", "basis": "Crime/Law and order/Violence/Vandalism; Morality/Individual behaviour; Local government/Council tax/Poll tax; Public services in general", "weight": 0.18},
    {"foundation": "loyalty", "basis": "Race relations/Immigration/Immigrants; Defence/Foreign affairs/International terrorism; Common Market/EU/Europe/Single European Currency; Countryside/Rural life", "weight": 0.13},
    {"foundation": "equality", "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; Pensions/Social security; Education/Schools; NHS/Hospitals/Healthcare", "weight": 0.10},
    {"foundation": "sanctity", "basis": "Morality/Individual behaviour; Drug abuse; Pollution/Environment", "weight": 0.04}
  ]
}
